CREATE TEMPORARY VIEW dwm_table_${grass_region_without_quote}  AS
SELECT
    platform
    ,user_id
    ,item_id
    ,shop_id
    ,order_id
    ,device_id
    ,feature_detail
    ,search_entrance
    ,search_mid
    ,is_ads
    ,keyword
    ,sort_type
    ,location
    ,scenario_tags
    ,scenario_tags AS dedup_scenario_tags
    ,true AS is_direct
    ,a.page_type
    ,page_section
    ,target_type
    ,COALESCE(b.original_page_type, a.page_type) AS original_page_type
    ,exp_group_ids
 
    ,order_cnt
    ,gmv
    ,gmv_local
    ,pc2_gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv

FROM dwd_omni_with_tag_${grass_region_without_quote} a
LEFT JOIN omni_search_mapping_scope_${grass_region_without_quote} b 
    ON a.page_type = b.mapped_page_type
UNION ALL
SELECT 
    platform
    ,user_id
    ,item_id
    ,shop_id
    ,order_id
    ,device_id
    ,source1_feature_detail AS feature_detail
    ,source1_search_entrance AS search_entrance
    ,source1_search_mid AS search_mid 
    ,is_ads
    ,source1_keyword AS keyword
    ,source1_sort_type AS sort_type
    ,source1_location AS location
    ,source1_scenario_tags AS scenario_tags
    ,array_except(source1_scenario_tags, COALESCE(scenario_tags, array())) as dedup_scenario_tags
    ,false AS is_direct
    ,source1_page_type AS page_type
    ,source1_page_section AS page_section 
    ,source1_target_type AS target_type 
    ,COALESCE(b.original_page_type, a.source1_page_type) AS original_page_type
    ,exp_group_ids
 
    ,order_cnt
    ,gmv
    ,gmv_local
    ,pc2_gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv

FROM 
    dwd_omni_with_tag_${grass_region_without_quote} a
LEFT JOIN omni_search_mapping_scope_${grass_region_without_quote} b 
    ON a.source1_page_type = b.mapped_page_type
WHERE
    COALESCE(source1_feature_detail, '') != ''
    AND source1_feature_detail != feature_detail
UNION ALL
SELECT
    platform
    ,user_id
    ,item_id
    ,shop_id
    ,order_id
    ,device_id
    ,source2_feature_detail AS feature_detail
    ,source2_search_entrance AS search_entrance
    ,source2_search_mid AS search_mid 
    ,is_ads
    ,source2_keyword AS keyword
    ,source2_sort_type AS sort_type
    ,source2_location AS location
    ,source2_scenario_tags AS scenario_tags
    ,array_except(array_except(source2_scenario_tags, COALESCE(scenario_tags, array())), COALESCE(source1_scenario_tags, array())) as dedup_scenario_tags
    ,false AS is_direct
    ,source2_page_type AS page_type
    ,source2_page_section AS page_section 
    ,source2_target_type AS target_type
    ,COALESCE(b.original_page_type, a.source2_page_type) AS original_page_type
    ,exp_group_ids
 
    ,order_cnt
    ,gmv
    ,gmv_local
    ,pc2_gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
    
FROM 
    dwd_omni_with_tag_${grass_region_without_quote} a
    LEFT JOIN omni_search_mapping_scope_${grass_region_without_quote} b 
    ON a.source2_page_type = b.mapped_page_type
WHERE
    COALESCE(source2_feature_detail, '') != ''
    AND source2_feature_detail != source1_feature_detail
    AND source2_feature_detail != feature_detail;

